head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil71006";
scwin.upd_etnAttachFile = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.upd_etnAttachFile = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_etnAttachFile') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_etnAttachFile"]');
        scwin.init_fillGen();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil71006.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "btn_Register", fn: function(){ return ((dma_readDataVO.get("lastSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.lastSaveStatCd"); })()) < '5'); } }, { id: "btn_Register_2", fn: function(){ return ((dma_readDataVO.get("lastSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.lastSaveStatCd"); })()) >='5'); } }, { id: "btn_EtnSub", fn: function(){ return ((dma_readDataVO.get("lastSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.lastSaveStatCd"); })()) >='5' && (dma_readDataVO.get("applStatusCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.applStatusCd"); })()) !== '03'); } }, { id: "btn_FileDelete", fn: function(){ return ((dlt_readDataFileVO.getCellData(0, "attachSeq") ?? (() => { throw new Error("unresolved:" + "entity.attachSeq"); })()) === (0+1) && (dma_readDataVO.get("lastSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.lastSaveStatCd"); })()) === '4'); } }, { id: "btn_FileDown", fn: function(){ return ((dlt_readDataFileVO.getCellData(0, "attachSeq") ?? (() => { throw new Error("unresolved:" + "entity.attachSeq"); })()) === (0+1)); } }, { id: "btn_FileDelete_r1", fn: function(){ return ((dlt_readDataFileVO.getCellData(0, "attachSeq") ?? (() => { throw new Error("unresolved:" + "entity.attachSeq"); })()) === (1+1) && (dma_readDataVO.get("lastSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.lastSaveStatCd"); })()) === '4'); } }, { id: "btn_FileDown_r1", fn: function(){ return ((dlt_readDataFileVO.getCellData(0, "attachSeq") ?? (() => { throw new Error("unresolved:" + "entity.attachSeq"); })()) === (1+1)); } }, { id: "btn_FileDelete_r2", fn: function(){ return ((dlt_readDataFileVO.getCellData(0, "attachSeq") ?? (() => { throw new Error("unresolved:" + "entity.attachSeq"); })()) === (2+1) && (dma_readDataVO.get("lastSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.lastSaveStatCd"); })()) === '4'); } }, { id: "btn_FileDown_r2", fn: function(){ return ((dlt_readDataFileVO.getCellData(0, "attachSeq") ?? (() => { throw new Error("unresolved:" + "entity.attachSeq"); })()) === (2+1)); } }, { id: "btn_FileDelete_r3", fn: function(){ return ((dlt_readDataFileVO.getCellData(0, "attachSeq") ?? (() => { throw new Error("unresolved:" + "entity.attachSeq"); })()) === (3+1) && (dma_readDataVO.get("lastSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.lastSaveStatCd"); })()) === '4'); } }, { id: "btn_FileDown_r3", fn: function(){ return ((dlt_readDataFileVO.getCellData(0, "attachSeq") ?? (() => { throw new Error("unresolved:" + "entity.attachSeq"); })()) === (3+1)); } }, { id: "btn_FileDelete_r4", fn: function(){ return ((dlt_readDataFileVO.getCellData(0, "attachSeq") ?? (() => { throw new Error("unresolved:" + "entity.attachSeq"); })()) === (4+1) && (dma_readDataVO.get("lastSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.lastSaveStatCd"); })()) === '4'); } }, { id: "btn_FileDown_r4", fn: function(){ return ((dlt_readDataFileVO.getCellData(0, "attachSeq") ?? (() => { throw new Error("unresolved:" + "entity.attachSeq"); })()) === (4+1)); } }, { id: "btn_FileDelete_r5", fn: function(){ return ((dlt_readDataFileVO.getCellData(0, "attachSeq") ?? (() => { throw new Error("unresolved:" + "entity.attachSeq"); })()) === (5+1) && (dma_readDataVO.get("lastSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.lastSaveStatCd"); })()) === '4'); } }, { id: "btn_FileDown_r5", fn: function(){ return ((dlt_readDataFileVO.getCellData(0, "attachSeq") ?? (() => { throw new Error("unresolved:" + "entity.attachSeq"); })()) === (5+1)); } }, { id: "btn_FileDelete_r6", fn: function(){ return ((dlt_readDataFileVO.getCellData(0, "attachSeq") ?? (() => { throw new Error("unresolved:" + "entity.attachSeq"); })()) === (6+1) && (dma_readDataVO.get("lastSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.lastSaveStatCd"); })()) === '4'); } }, { id: "btn_FileDown_r6", fn: function(){ return ((dlt_readDataFileVO.getCellData(0, "attachSeq") ?? (() => { throw new Error("unresolved:" + "entity.attachSeq"); })()) === (6+1)); } }, { id: "btn_FileDelete_r7", fn: function(){ return ((dlt_readDataFileVO.getCellData(0, "attachSeq") ?? (() => { throw new Error("unresolved:" + "entity.attachSeq"); })()) === (7+1) && (dma_readDataVO.get("lastSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.lastSaveStatCd"); })()) === '4'); } }, { id: "btn_FileDown_r7", fn: function(){ return ((dlt_readDataFileVO.getCellData(0, "attachSeq") ?? (() => { throw new Error("unresolved:" + "entity.attachSeq"); })()) === (7+1)); } }, { id: "btn_FileDelete_r8", fn: function(){ return ((dlt_readDataFileVO.getCellData(0, "attachSeq") ?? (() => { throw new Error("unresolved:" + "entity.attachSeq"); })()) === (8+1) && (dma_readDataVO.get("lastSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.lastSaveStatCd"); })()) === '4'); } }, { id: "btn_FileDown_r8", fn: function(){ return ((dlt_readDataFileVO.getCellData(0, "attachSeq") ?? (() => { throw new Error("unresolved:" + "entity.attachSeq"); })()) === (8+1)); } }, { id: "btn_FileDelete_r9", fn: function(){ return ((dlt_readDataFileVO.getCellData(0, "attachSeq") ?? (() => { throw new Error("unresolved:" + "entity.attachSeq"); })()) === (9+1) && (dma_readDataVO.get("lastSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.lastSaveStatCd"); })()) === '4'); } }, { id: "btn_FileDown_r9", fn: function(){ return ((dlt_readDataFileVO.getCellData(0, "attachSeq") ?? (() => { throw new Error("unresolved:" + "entity.attachSeq"); })()) === (9+1)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_73", entity: "dlt_readDataFileVO", countIds: [], cells: [{ childId: "btn_FileDown", fn: function (v, i) { return String(v("attachFileNm")); } }] },
        { genId: "c_foreach_73_r1", entity: "dlt_readDataFileVO", countIds: [], cells: [{ childId: "btn_FileDown_r1", fn: function (v, i) { return String(v("attachFileNm")); } }] },
        { genId: "c_foreach_73_r2", entity: "dlt_readDataFileVO", countIds: [], cells: [{ childId: "btn_FileDown_r2", fn: function (v, i) { return String(v("attachFileNm")); } }] },
        { genId: "c_foreach_73_r3", entity: "dlt_readDataFileVO", countIds: [], cells: [{ childId: "btn_FileDown_r3", fn: function (v, i) { return String(v("attachFileNm")); } }] },
        { genId: "c_foreach_73_r4", entity: "dlt_readDataFileVO", countIds: [], cells: [{ childId: "btn_FileDown_r4", fn: function (v, i) { return String(v("attachFileNm")); } }] },
        { genId: "c_foreach_73_r5", entity: "dlt_readDataFileVO", countIds: [], cells: [{ childId: "btn_FileDown_r5", fn: function (v, i) { return String(v("attachFileNm")); } }] },
        { genId: "c_foreach_73_r6", entity: "dlt_readDataFileVO", countIds: [], cells: [{ childId: "btn_FileDown_r6", fn: function (v, i) { return String(v("attachFileNm")); } }] },
        { genId: "c_foreach_73_r7", entity: "dlt_readDataFileVO", countIds: [], cells: [{ childId: "btn_FileDown_r7", fn: function (v, i) { return String(v("attachFileNm")); } }] },
        { genId: "c_foreach_73_r8", entity: "dlt_readDataFileVO", countIds: [], cells: [{ childId: "btn_FileDown_r8", fn: function (v, i) { return String(v("attachFileNm")); } }] },
        { genId: "c_foreach_73_r9", entity: "dlt_readDataFileVO", countIds: [], cells: [{ childId: "btn_FileDown_r9", fn: function (v, i) { return String(v("attachFileNm")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

// [A] 초기 목록 미해결 — 자기 목록을 채우는 tx 가 5개다(tx_fn_EtnChangePage, tx_fn_Register, tx_fn_EtnSub, tx_fn_Search) — 어느 것이 «열자마자» 인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Register_onclick
 * @description 「저장」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Register_onclick = async function(e){
    try {
        await scwin.register()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil71006.btn_Register_onclick' }); }
};

