 */
scwin.search = async function () {
    form = (document.etnListForm || { elements: [] });
    form.action = "LossLimitEtnList.do";
    $c.util.getComponent('dma_SearchReq').set('method', 'lossLimitSearchList');
    await scwin.tx_fn_Search();
};

/**
 * @method
 * @name fileDown
 * @description file Down 처리
 * @param {*} bzProcsNo bzProcsNo
 * @param {*} attachSeq attachSeq
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileDown = async function (bzProcsNo, attachSeq) {
    form = (document.fileForm || { elements: [] });
    $c.util.getComponent('dma_FileDownReq').set('bzProcsNo', bzProcsNo);
    $c.util.getComponent('dma_FileDownReq').set('attachSeq', attachSeq);
    $c.util.getComponent('dma_FileDownReq').set('method', 'downloadAttachFile');
    form.action = 'FileDownload.do';
    await scwin.tx_fn_FileDown();
};

/**
 * @method
 * @name fileDelete
 * @description file Delete 처리
 * @param {*} bzProcsNo bzProcsNo
 * @param {*} attachSeq attachSeq
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileDelete = async function (bzProcsNo, attachSeq) {
    if (!await $c.fil.confirmJob('D')) {
        return;
    }
    form = (document.etnListForm || { elements: [] });
    $c.util.getComponent('dma_FileDeleteReq').set('bzProcsNo', bzProcsNo);
    $c.util.getComponent('dma_FileDeleteReq').set('attachSeq', attachSeq);
    $c.util.getComponent('dma_FileDeleteReq').set('method', 'lossLimitDeleteAttachFile');
    form.action = 'LossLimitEtnList.do';
    await scwin.tx_fn_FileDelete();
};
